// Glyph outlines for the editable inscription, and a pure single-line layout.
//
// The outlines come from src/core/glyphs/roboto-900.json (generated by scripts/build-glyphs.mjs from
// Roboto Black, SIL OFL 1.1, see glyphs/OFL.txt). Contours follow the Lottie path convention: closed,
// y axis DOWN, `v` absolute vertices, `i`/`o` tangents relative to their vertex. A cubic segment
// from vertex k to k+1 has control points v[k] + o[k] and v[k+1] + i[k+1].
// Pure TS: no DOM, never mutates its inputs.

export interface GlyphContour {
  v: [number, number][]
  i: [number, number][]
  o: [number, number][]
}

export interface GlyphSet {
  unitsPerEm: number
  /** Cap height in font units. */
  capHeight: number
  /** Space has no contours. */
  glyphs: Record<string, { advance: number; contours: GlyphContour[] }>
  /** 'AV' -> font units; non-zero pairs within the set only. */
  kerning: Record<string, number>
}

export interface Box { x0: number; y0: number; x1: number; y1: number }

export interface PlacedGlyph {
  char: string
  /** In box coordinates (same convention as the set: closed, y down, relative tangents). */
  contours: GlyphContour[]
  /** Tight ink box in box coordinates (curve extent, not control points); null for space. */
  bounds: Box | null
}

type Pt = [number, number]

/** Parameters t in (0, 1) where one coordinate of the cubic a,b,c,d has zero slope. */
function extremaT(a: number, b: number, c: number, d: number): number[] {
  // B'(t) / 3 = (A - 2B + C) t^2 + 2 (B - A) t + A, with A = b - a, B = c - b, C = d - c.
  const A = b - a
  const B = c - b
  const C = d - c
  const qa = A - 2 * B + C
  const qb = 2 * (B - A)
  const roots: number[] = []
  if (Math.abs(qa) < 1e-12) {
    if (Math.abs(qb) > 1e-12) roots.push(-A / qb)
  } else {
    const disc = qb * qb - 4 * qa * A
    if (disc >= 0) {
      const root = Math.sqrt(disc)
      roots.push((-qb + root) / (2 * qa), (-qb - root) / (2 * qa))
    }
  }
  return roots.filter((t) => t > 0 && t < 1)
}

function cubicAt(a: number, b: number, c: number, d: number, t: number): number {
  const u = 1 - t
  return u * u * u * a + 3 * u * u * t * b + 3 * u * t * t * c + t * t * t * d
}

/** Tight box of a closed contour: vertices plus the interior extrema of every cubic segment. */
function contourBounds(c: GlyphContour): Box {
  let x0 = Infinity
  let y0 = Infinity
  let x1 = -Infinity
  let y1 = -Infinity
  const grow = (x: number, y: number): void => {
    if (x < x0) x0 = x
    if (x > x1) x1 = x
    if (y < y0) y0 = y
    if (y > y1) y1 = y
  }
  const n = c.v.length
  for (let k = 0; k < n; k++) {
    const p0 = c.v[k]
    const p3 = c.v[(k + 1) % n]
    grow(p0[0], p0[1])
    const o = c.o[k]
    const i = c.i[(k + 1) % n]
    if (o[0] === 0 && o[1] === 0 && i[0] === 0 && i[1] === 0) continue // straight segment
    const p1: Pt = [p0[0] + o[0], p0[1] + o[1]]
    const p2: Pt = [p3[0] + i[0], p3[1] + i[1]]
    const ts = [...extremaT(p0[0], p1[0], p2[0], p3[0]), ...extremaT(p0[1], p1[1], p2[1], p3[1])]
    for (const t of ts) {
      grow(cubicAt(p0[0], p1[0], p2[0], p3[0], t), cubicAt(p0[1], p1[1], p2[1], p3[1], t))
    }
  }
  return { x0, y0, x1, y1 }
}

function unionBounds(boxes: Box[]): Box | null {
  if (boxes.length === 0) return null
  return {
    x0: Math.min(...boxes.map((b) => b.x0)),
    y0: Math.min(...boxes.map((b) => b.y0)),
    x1: Math.max(...boxes.map((b) => b.x1)),
    y1: Math.max(...boxes.map((b) => b.y1)),
  }
}

/**
 * Lay `text` out on one line inside `box` (coordinates y down).
 *
 * Pen positions use advance widths plus kerning. One uniform scale
 * `s = min(boxHeight / capHeight, boxWidth / inkWidth)` is applied, where inkWidth is the horizontal
 * ink extent of the line in font units (leading/trailing spaces carry no ink). The block
 * (ink width x cap height) is centred in the box: the baseline sits at
 * `y1 - (boxHeight - capHeight * s) / 2` and the ink extent is centred on `(x0 + x1) / 2`.
 *
 * Throws if a character is missing from the set, or if the box has no positive width and height.
 * Returns fresh contours (the set is never aliased or mutated).
 */
export function layoutLine(set: GlyphSet, text: string, box: Box): PlacedGlyph[] {
  const boxW = box.x1 - box.x0
  const boxH = box.y1 - box.y0
  if (!(boxW > 0 && boxH > 0)) {
    throw new RangeError(`layoutLine: box must have positive width and height, got ${boxW} x ${boxH}`)
  }

  const chars = [...text]
  const glyphs = chars.map((ch) => {
    if (!Object.hasOwn(set.glyphs, ch)) throw new Error(`layoutLine: no glyph for ${JSON.stringify(ch)}`)
    return set.glyphs[ch]
  })

  // Pen origin of every glyph and its ink box in font units.
  const pens: number[] = []
  const local = glyphs.map((g) => unionBounds(g.contours.map(contourBounds)))
  let pen = 0
  for (let n = 0; n < chars.length; n++) {
    if (n > 0) pen += set.kerning[chars[n - 1] + chars[n]] ?? 0
    pens.push(pen)
    pen += glyphs[n].advance
  }

  let inkMin = Infinity
  let inkMax = -Infinity
  local.forEach((b, n) => {
    if (!b) return
    inkMin = Math.min(inkMin, pens[n] + b.x0)
    inkMax = Math.max(inkMax, pens[n] + b.x1)
  })
  const inkWidth = inkMax > inkMin ? inkMax - inkMin : 0

  const heightScale = boxH / set.capHeight
  const s = inkWidth > 0 ? Math.min(heightScale, boxW / inkWidth) : heightScale
  const baseline = box.y1 - (boxH - set.capHeight * s) / 2
  const originX = inkWidth > 0 ? (box.x0 + box.x1) / 2 - (s * (inkMin + inkMax)) / 2 : box.x0 + boxW / 2

  return chars.map((char, n): PlacedGlyph => {
    const px = originX + s * pens[n]
    const moved = (p: Pt): Pt => [px + s * p[0], baseline + s * p[1]]
    const scaled = (p: Pt): Pt => [s * p[0], s * p[1]]
    const b = local[n]
    return {
      char,
      contours: glyphs[n].contours.map((c) => ({ v: c.v.map(moved), i: c.i.map(scaled), o: c.o.map(scaled) })),
      bounds: b && { x0: px + s * b.x0, y0: baseline + s * b.y0, x1: px + s * b.x1, y1: baseline + s * b.y1 },
    }
  })
}
